<?php
header('Content-Type: text/html; charset=UTF-8');
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('Expires: 0');
session_set_cookie_params(['httponly' => true, 'samesite' => 'Lax']);
session_start();
$startAtLunarBase = (string)($_GET['spawn'] ?? '') === 'moon';
$mpUserId = (int)($_SESSION['user_id'] ?? 0);
if ($mpUserId < 1) {
  $next = rawurlencode('index.php');
  header('Location: login.php?next=' . $next, true, 302);
  exit;
}
$mobileControlsVersion = substr(hash_file('sha256', __DIR__ . '/js/mobile-controls.js'), 0, 16);
$worldCatalog = require __DIR__ . '/world-catalog.php';
$bodies = $worldCatalog['bodies'];
$stationIds = $worldCatalog['stationIds'];
$missionBodyIds = $worldCatalog['missionBodyIds'];
$mpAuthenticated = $mpUserId > 0;
$mpUsername = (string)($_SESSION['username'] ?? '');
// Endpoint para persistir a posiÃ§Ã£o da nave no servidor.
$positionAction = $_GET['action'] ?? '';
$positionSessionKey = hash('sha256', session_id());
session_write_close(); // Libera o bloqueio antes das consultas ao banco.
$worldScaleVersion = 2;
$positionDatabase = static function (): PDO {
  require_once __DIR__ . '/database/connection.php';
  $pdo = db();
  $pdo->exec("CREATE TABLE IF NOT EXISTS user_ship_positions (
    user_id BIGINT UNSIGNED NOT NULL,
    position_data JSON NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id),
    CONSTRAINT fk_user_ship_positions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  ) ENGINE=InnoDB");
  $pdo->exec("CREATE TABLE IF NOT EXISTS guest_ship_positions (
    session_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    position_data JSON NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (session_key)
  ) ENGINE=InnoDB");
  return $pdo;
};
$loadPositionState = static function () use ($mpAuthenticated, $mpUserId, $positionSessionKey, $positionDatabase, $worldScaleVersion): array {
  $pdo = $positionDatabase();
  if ($mpAuthenticated) {
    $query = $pdo->prepare('SELECT position_data FROM user_ship_positions WHERE user_id=? LIMIT 1');
    $query->execute([$mpUserId]);
  } else {
    $query = $pdo->prepare('SELECT position_data FROM guest_ship_positions WHERE session_key=? LIMIT 1');
    $query->execute([$positionSessionKey]);
  }
  $stored = $query->fetchColumn();
  $snapshot = is_string($stored) ? json_decode($stored, true) : null;
  if (!is_array($snapshot)) return [];
  if ((int)($snapshot['worldScaleVersion'] ?? 1) < $worldScaleVersion) {
    foreach (['x','z'] as $axis) if (isset($snapshot[$axis]) && is_numeric($snapshot[$axis])) $snapshot[$axis] = (float)$snapshot[$axis] * 4.5;
    $snapshot['worldScaleVersion'] = $worldScaleVersion;
    $encoded = json_encode($snapshot, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    if ($mpAuthenticated) {
      $update = $pdo->prepare('UPDATE user_ship_positions SET position_data=? WHERE user_id=?');
      $update->execute([$encoded, $mpUserId]);
    } else {
      $update = $pdo->prepare('UPDATE guest_ship_positions SET position_data=? WHERE session_key=?');
      $update->execute([$encoded, $positionSessionKey]);
    }
  }
  return $snapshot;
};
$savePositionState = static function (array $snapshot) use ($mpAuthenticated, $mpUserId, $positionSessionKey, $positionDatabase): bool {
  $pdo = $positionDatabase();
  $encoded = json_encode($snapshot, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
  if ($mpAuthenticated) {
    $save = $pdo->prepare('INSERT INTO user_ship_positions (user_id,position_data) VALUES (?,?) ON DUPLICATE KEY UPDATE position_data=VALUES(position_data)');
    return $save->execute([$mpUserId, $encoded]);
  }
  $save = $pdo->prepare('INSERT INTO guest_ship_positions (session_key,position_data) VALUES (?,?) ON DUPLICATE KEY UPDATE position_data=VALUES(position_data)');
  return $save->execute([$positionSessionKey, $encoded]);
};
if ($positionAction === 'load-position' || $positionAction === 'save-position') {
  header('Content-Type: application/json; charset=utf-8');
  if ($positionAction === 'load-position') {
    try {
      $snapshot = $loadPositionState();
    } catch (Throwable $error) {
      error_log('Falha ao carregar posiÃ§Ã£o persistida da nave: ' . $error->getMessage());
      http_response_code(503);
      echo json_encode(['error'=>'Banco de dados indisponÃ­vel para carregar a posiÃ§Ã£o da nave']);
      exit;
    }
    echo json_encode($snapshot ?: ['x'=>0,'y'=>0,'z'=>0,'yaw'=>0,'roll'=>0,'fuel'=>1000,'shipClass'=>'explorer','fleet'=>[],'worldScaleVersion'=>$worldScaleVersion], JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    exit;
  }

  if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    echo json_encode(['error'=>'MÃ©todo nÃ£o permitido']);
    exit;
  }
  $position = json_decode(file_get_contents('php://input'), true);
  $fields = ['x','y','z','yaw','roll'];
  if (!is_array($position)) {
    http_response_code(400);
    echo json_encode(['error'=>'PosiÃ§Ã£o invÃ¡lida']);
    exit;
  }
  $safePosition = [];
  foreach ($fields as $field) {
    if (!isset($position[$field]) || !is_numeric($position[$field]) || !is_finite((float)$position[$field])) {
      http_response_code(400);
      echo json_encode(['error'=>'Coordenada invÃ¡lida']);
      exit;
    }
    $safePosition[$field] = in_array($field, ['x','z'], true) ? max(-450000, min(450000, (float)$position[$field])) : (float)$position[$field];
  }
  $safePosition['worldScaleVersion'] = $worldScaleVersion;
  $cargo = is_array($position['cargo'] ?? null) ? $position['cargo'] : [];
  $safePosition['cargo'] = [];
  foreach (['Ferro','Niquel','Cobalto','Gelo'] as $mineral) {
    $safePosition['cargo'][$mineral] = max(0, (int)($cargo[$mineral] ?? 0));
  }
  $safePosition['resources'] = [];
  $resources = is_array($position['resources'] ?? null) ? $position['resources'] : [];
  foreach ($resources as $code => $stock) {
    if (is_string($code) && preg_match('/^(ice_\\d{3}|europa|ganymede|callisto|tita|encelado|iapeto|titania|tritao)$/', $code)) $safePosition['resources'][$code] = max(0, min(1000000, (int)$stock));
  }
  $safePosition['credits'] = max(0, (int)($position['credits'] ?? 0));
  $safePosition['shipClass'] = in_array($position['shipClass'] ?? '', ['explorer','prospector','scout','freighter','attack'], true) ? $position['shipClass'] : 'explorer';
  $safePosition['hull'] = max(0, min(($safePosition['shipClass'] === 'attack' ? 180 : ($safePosition['shipClass'] === 'freighter' ? 170 : 100)), (int)($position['hull'] ?? 100)));
  $safeFuelCapacity = ['prospector'=>850,'scout'=>1500,'freighter'=>1800][$safePosition['shipClass']] ?? 1000;
  $safePosition['fuel'] = max(0, min($safeFuelCapacity, (float)($position['fuel'] ?? $safeFuelCapacity)));
  $safePosition['fleet'] = is_array($position['fleet'] ?? null) ? array_slice($position['fleet'], 0, 40) : [];
  $weapon = is_array($position['weapon'] ?? null) ? $position['weapon'] : [];
  $weaponKinds = ['pulse','ion','heavy','singularity'];
  $weaponKind = in_array($weapon['kind'] ?? '', $weaponKinds, true) ? $weapon['kind'] : 'pulse';
  $ownedWeapons = is_array($weapon['owned'] ?? null) ? array_values(array_unique(array_filter($weapon['owned'], fn($kind) => is_string($kind) && in_array($kind, $weaponKinds, true)))) : [];
  if (!empty($weapon['installed']) && !$ownedWeapons) $ownedWeapons[] = 'pulse';
  $safeDamage = (int)($weapon['damage'] ?? 24);
  $safePosition['weapon'] = [
    'installed' => !empty($weapon['installed']),
    'kind' => $weaponKind,
    'owned' => $ownedWeapons,
    'damage' => in_array($safeDamage, [5,10,25,55,150], true) ? $safeDamage : 5,
    'ammo' => min(90, max(0, (int)($weapon['ammo'] ?? 0)))
  ];
  $destroyed = is_array($position['destroyedAsteroids'] ?? null) ? $position['destroyedAsteroids'] : [];
  $safePosition['destroyedAsteroids'] = array_values(array_filter($destroyed, fn($id) => is_string($id) && preg_match('/^asteroide_\d{3,4}$/', $id)));
  $mission = is_array($position['mission'] ?? null) ? $position['mission'] : null;
  $safePosition['mission'] = null;
  if ($mission) {
        $knownBodies = $missionBodyIds;
        $knownStations = $stationIds;
    $missionType = $mission['type'] ?? '';
    $missionPhase = $mission['phase'] ?? '';
    $missionOrigin = $mission['origin'] ?? '';
    $missionDestination = $mission['destination'] ?? '';
    if (in_array($missionType, ['passengers','material'], true)
      && in_array($missionPhase, ['pickup','delivery'], true)
      && in_array($missionOrigin, $knownStations, true)
      && in_array($missionDestination, $knownBodies, true)) {
      $missionAmount = max(1, min($missionType === 'passengers' ? 500 : 2000, (int)($mission['amount'] ?? 1)));
      $safePosition['mission'] = [
        'id' => substr((string)($mission['id'] ?? ''), 0, 100),
        'type' => $missionType,
        'material' => $mission['material'] ?? '',
        'origin' => $missionOrigin,
        'destination' => $missionDestination,
        'amount' => $missionAmount,
        'delivered' => max(0, min($missionAmount, (int)($mission['delivered'] ?? 0))),
        'onboard' => max(0, min($missionType === 'passengers' ? 12 : 2000, (int)($mission['onboard'] ?? 0))),
        'reward' => max(0, min(10000000, (int)($mission['reward'] ?? 0))),
        'paid' => max(0, min(10000000, (int)($mission['paid'] ?? 0))),
        'phase' => $missionPhase,
        'acceptedAt' => substr((string)($mission['acceptedAt'] ?? ''), 0, 40)
      ];
    }
  }
  $safePosition['savedAt'] = date(DATE_ATOM);
  try {
    $saved = $savePositionState($safePosition);
  } catch (Throwable $error) {
    error_log('Falha ao salvar posiÃ§Ã£o persistida da nave: ' . $error->getMessage());
    $saved = false;
  }
  if (!$saved) {
    http_response_code(500);
    echo json_encode(['error'=>'NÃ£o foi possÃ­vel salvar a posiÃ§Ã£o']);
    exit;
  }
  echo json_encode(['saved'=>true]);
  exit;
}
if ($positionAction === 'load-map') {
  header('Content-Type: application/json; charset=utf-8');
  try {
    $savedPosition = $loadPositionState();
  } catch (Throwable $error) {
    error_log('Falha ao carregar posiÃ§Ã£o da nave para o mapa: ' . $error->getMessage());
    http_response_code(503);
    echo json_encode(['error'=>'Banco de dados indisponÃ­vel para carregar a posiÃ§Ã£o da nave']);
    exit;
  }
  $mapBodies = array_values(array_filter($bodies, fn($body) => $body['type'] !== 'Asteroide'));
  echo json_encode([
    'bodies' => $mapBodies,
    'ship' => ['x' => (float)($savedPosition['x'] ?? 0), 'z' => (float)($savedPosition['z'] ?? 0)],
    'bounds' => 450000
  ], JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
  exit;
}
$bodies = array_merge($bodies, worldGenerateAsteroids(), worldGenerateIceAsteroids());
?>
