function applyShipSnapshot(p){if(!p)return;window.playerShipVisualName=String(p.name||window.playerShipVisualName||'');setShipModel(p.shipClass||'explorer');fuelCapacityUnits=Math.max(1,Number(p.fuelCapacity)||fuelCapacityUnits);cargoCapacityKg=Math.max(1,Number(p.cargoCapacity)||cargoCapacityKg);fuelUnits=Math.max(0,Math.min(fuelCapacityUnits,Number(p.fuel??fuelCapacityUnits)||0));if(Array.isArray(p.fleet)){localFleet=p.fleet;localShipCounter=Math.max(localShipCounter,...localFleet.map(ship=>Number(ship.id)||0).map(id=>id+1))}window.crewRole=p.role||'pilot';window.crewDocked=Number(p.stationId||0)>0;document.body.classList.toggle('copilot-mode',window.crewRole==='copilot');document.body.classList.toggle('station-docked-mode',window.crewDocked);for(const axis of ['x','z','yaw','roll'])if(Number.isFinite(Number(p[axis])))player[axis]=Number(p[axis]);cameraYaw=0;cameraPitch=0;if(p.cargo)for(const mineral of Object.keys(miningState.oreCounts))miningState.oreCounts[mineral]=Math.max(0,Number(p.cargo[mineral])||0);if(p.resources)for(const [code,stock] of Object.entries(p.resources)){const body=bodies.find(item=>(item.code||item.id)===code);if(body){if(body.ice)body.remainingIce=Math.max(0,Number(stock)||0);else if(body.iceSource)body.iceKg=Math.max(0,Number(stock)||0)}}miningState.ore=Object.values(miningState.oreCounts).reduce((sum,value)=>sum+value,0);credits=Math.max(0,Math.floor(Number(p.credits)||0));fuelCapacityUnits=Math.max(1,Number(p.fuelCapacity)||fuelCapacityUnits);cargoCapacityKg=Math.max(1,Number(p.cargoCapacity)||cargoCapacityKg);fuelUnits=Math.max(0,Math.min(fuelCapacityUnits,Number(p.fuel??fuelCapacityUnits)||0));energyUnits=Math.max(0,Number(p.energy)||0);shipHull=Math.max(0,Number(p.hull??100));if(p.weapon){weaponSystem.mounts=Array.isArray(p.weapon.mounts)?p.weapon.mounts.map(m=>({kind:m.kind,ammo:Number(m.ammo)||0,maxAmmo:Number(m.maxAmmo)||90,damage:Number(m.damage)||5})):[];weaponSystem.kind=['pulse','ion','heavy','singularity'].includes(p.weapon.ki