window.crewGame={api:multiplayerApi,enabled:multiplayerEnabled,applyRole:(role,activeCrew=false)=>{window.crewRole=role;document.body.classList.toggle('copilot-mode',role==='copilot');document.body.classList.toggle('dual-crew',!!activeCrew)},refreshShip:()=>fetch(multiplayerApi+'?action=state',{cache:'no-store'}).then(r=>r.json()).then(applyShipSnapshot),attackStation:async code=>{const r=await fetch(multiplayerApi+'?action=station-attack',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({station:code})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Falha no ataque');const shot=document.createElement('i');shot.className='crew-beam';document.body.appendChild(shot);setTimeout(()=>shot.remove(),520);document.body.classList.remove('station-hit-flash');void document.body.offsetWidth;document.body.classList.add('station-hit-flash');setTimeout(()=>document.body.classList.remove('station-hit-flash'),650);return d}};
