        pod(-55,-24,44,28);pod(0,-31,62,42);pod(55,-24,44,28);
        ctx.strokeStyle='#aecfd2';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-33,-26);ctx.lineTo(-20,-31);ctx.moveTo(31,-31);ctx.lineTo(34,-26);ctx.stroke();
