            ctx.strokeStyle='rgba(105,193,226,.8)';ctx.lineWidth=1;for(let i=1;i<4;i++){ctx.beginPath();ctx.moveTo(x-19+i*9.5,y-12);ctx.lineTo(x-19+i*9.5,y+12);ctx.stroke()}ctx.beginPath();ctx.moveTo(x-19,y);ctx.lineTo(x+19,y);ctx.stroke();
