    const pod=(x,y,w=30,h=20)=>{const g=ctx.createLinearGradient(x,y-h/2,x,y+h/2);g.addColorStop(0,'#b4c7c2');g.addColorStop(.35,metal);g.addColorStop(1,'#122733');ctx.fillStyle=g;ctx.strokeStyle='#d2e2dc';ctx.lineWidth=1.5;ctx.beginPath();ctx.roundRect(x-w/2,y-h/2,w,h,h*.42);ctx.fill();ctx.stroke();ctx.fillStyle=glow;ctx.shadowColor=glow;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(x,y,2.1,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0};
    const panel=(x,y,w,h,a=0)=>{ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#092446';ctx.strokeStyle=glow;ctx.lineWidth=1.6;ctx.fillRect(-w/2,-h/2,w,h);ctx.strokeRect(-w/2,-h/2,w,h);ctx.strokeStyle='rgba(106,179,220,.6)';ctx.lineWidth=.8;for(let i=1;i<5;i++){ctx.beginPath();ctx.moveTo(-w/2+w*i/5,-h/2);ctx.lineTo(-w/2+w*i/5,h/2);ctx.stroke()}for(let i=1;i<8;i++){ctx.beginPath();ctx.moveTo(-w/2,-h/2+h*i/8);ctx.lineTo(w/2,-h/2+h*i/8);ctx.stroke()}ctx.restore()};
    const ring=(x,y,rx,ry,w=10)=>{ctx.strokeStyle='#182e3a';ctx.lineWidth=w+5;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.stroke();ctx.strokeStyle=metal;ctx.lineWidth=w;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.stroke();ctx.strokeStyle=glow;ctx.lineWidth=1.6;ctx.beginPath();ctx.ellipse(x,y,rx-w*.65,ry-w*.65,0,0,Math.PI*2);ctx.stroke()};
    const core=(x=0,y=0)=>{let g=ctx.createRadialGradient(x-3,y-4,1,x,y,17);g.addColorStop(0,'#efffff');g.addColorStop(.25,glow);g.addColorStop(1,'#08202a');ctx.fillStyle=g;ctx.strokeStyle=glow;ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,17,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowColor=glow;ctx.shadowBlur=18;ctx.beginPath();ctx.arc(x,y,4+Math.sin(t*3)*1.2,0,Math.PI*2);ctx.fillStyle='#f0ffff';ctx.fill();ctx.shadowBlur=0};

    if(style===1){ // Bastilha: anel de perfil e eixo longo de defesa
        line(-195,0,195,0,12);line(-184,-6,185,-6,1.4,'#d7e3dd');ring(-62,0,34,78,11);
        for(let i=0;i<9;i++){let a=i*Math.PI*2/9+t*.018;line(-62+Math.cos(a)*23,Math.sin(a)*58,-62+Math.cos(a)*7,Math.sin(a)*18,2.5,'#9eb6b5')}
        pod(-172,0,39,28);pod(-113,0,51,38);pod(7,0,61,44);pod(91,0,50,36);pod(170,0,43,30);
        line(114,-4,130,-57,3);line(114,4,130,57,3);panel(151,-78,48,38,-.12);panel(151,78,48,38,.12);panel(-186,-65,25,58,-.08);panel(-186,65,25,58,.08);core(-62,0);
    }else if(style===2){ // Khepri: perfil lateral do estÃ¡leiro, com eixo aberto e docas cilÃ­ndricas
        line(-205,7,205,7,12,'#284654');line(-205,0,205,0,7,'#c2d4d0');line(-205,-5,205,-5,1.5,'#e2ebe4');
        line(-177,-23,171,-23,4,'#87a8ad');line(-177,23,171,23,4,'#567c87');
        for(let x=-155;x<=150;x+=51){line(x,-23,x+14,23,2,'#85a5aa');line(x,23,x+14,-23,1.4,'#496b77')}
        pod(-151,0,42,27);pod(-84,0,71,43);pod(4,0,58,37);pod(91,0,76,45);pod(174,0,48,30);core(4,0);
        line(-20,-24,-20,-63,3);line(-20,24,-20,63,3);panel(-20,-91,38,54);panel(-20,91,38,54);
        line(112,-22,138,-59,4);line(112,22,138,59,4);panel(153,-77,51,31,-.08);panel(153,77,51,31,.08);
        // A narrow gantry and end cranes read as depth from the side, not as a flat rectangular frame.
        line(-196,-32,-196,32,4);line(197,-34,197,34,4);line(-196,-32,-170,-23,2);line(197,34,171,23,2);pod(-196,-39,22,16);pod(197,41,22,16);
    }else if(style===3){ // VÃ©sper: terminal de transferÃªncia com dois braÃ§os de doca
        line(-175,0,188,0,10);ring(-61,0,32,65,8);pod(-158,0,40,29);pod(14,0,73,48);pod(111,0,50,34);pod(185,0,35,25);
        line(58,-8,87,-58,5);line(58,8,87,58,5);pod(91,-64,39,27);pod(91,64,39,27);panel(-153,-78,34,63,-.1);panel(-153,78,34,63,.1);panel(133,-103,47,30,-.06);panel(133,103,47,30,.06);core(-61,0);
    }else if(style===4){ // Ãcaro: colÃ´nia lateral de habitats pressurizados
        line(-180,0,184,0,9);ring(-97,0,28,55,8);pod(-148,0,48,36);pod(-40,0,82,55);pod(48,0,72,49);pod(137,0,69,46);
