window.marketSellWeapon=async(action,payout)=>{const kinds={buyCannon:'pulse',buyIon:'ion',buyHeavy:'heavy',buySingularity:'singularity'},kind=kinds[action];let amount=Math.max(0,Math.floor(Number(payout)||0));if(multiplayerEnabled){const saleItem=kind||(action==='buyAmmo'?'ammo':action==='buyUpgrade'?'upgrade':'');if(!saleItem)throw new Error('Item nao pode ser vendido.');const result=await socialRequest('weapon-sale',{station:selected.id,item:saleItem});amount=Number(result.payout)||0;credits=Number(result.credits)||credits}if(kind){if(!weaponSystem.owned.includes(kind))return;weaponSystem.owned=weaponSystem.owned.filter(item=>item!==kind);if(weaponSystem.kind===kind){const fallback=weaponSystem.owned.includes('pulse')?'pulse':weaponSystem.owned[0];if(fallback){weaponSystem.kind=fallback;weaponSystem.installed=true;weaponSystem.damage=({pulse:weaponSystem.upgraded?10:5,ion:25,heavy:55,singularity:150})[fallback];weaponSystem.maxAmmo=fallback==='singularity'?30:90;weaponSystem.ammo=Math.min(weaponSystem.ammo,weaponSystem.maxAmmo)}else{weaponSystem.kind='pulse';weaponSystem.installed=false;weaponSystem.damage=5;weaponSystem.ammo=0;weaponSystem.maxAmmo=90}}}else if(action==='buyAmmo'&&weaponSystem.ammo>0){weaponSystem.ammo=0}else if(action==='buyUpgrade'&&weaponSystem.upgraded){weaponSystem.upgraded=false;if(weaponSystem.kind==='pulse')weaponSystem.damage=Math.round(5*(shipClass==='attack'?1.35:1))}else return;if(!multiplayerEnabled)credits+=amount;weaponSystem.weightKg=weaponSystem.installed?(weaponMountWeights[weaponSystem.kind]||0):0;setStationMessage('Item vendido por '+amount.toLocaleString('pt-BR')+' CR.');refreshStationMarket();updateHud();await savePosition()};
function purchaseWeapon(kind,price){if(weaponSystem.owned.includes(kind)){equipWeapon(kind);return}if(credits<price){setStationMessage(insufficientCreditsMessage(price));return}const mass=weaponMountWeights[kind]||0,load=Object.values(miningState.oreCounts).reduce((sum,value)=>sum+(Number(value)||0),0);if(load+mass+fuelCargoWeight()+passengerCargoWeight()>cargoCapacityKg){setStationMessage('O canhao ocupa '+mass+' kg. Libere espaco antes de instalar.');return}credits-=price;if(!equipWeapon(kind))return;setStationMessage(weaponLabel(kind)+' adquirido e equipado.');savePosition();}
for(const id of ['buyCannon','buyAmmo','buyUpgrade','buyIon','buyHeavy'])document.querySelector('#'+id).addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();const button=event.currentTarget;if(button.disabled)return;if(id==='buyCannon'){purchaseWeapon('pulse',120)}else if(id==='buyIon'){purchaseWeapon('ion',260)}else if(id==='buyHeavy'){purchaseWeapon('heavy',500)}else if(id==='buyAmmo'){if(!weaponSystem.installed)return;if(credits<30){setStationMessage(insufficientCreditsMessage(30));return}credits-=30;const charge=Math.min(30,weaponSystem.maxAmmo-weaponSystem.ammo);weaponSystem.ammo+=charge;setStationMessage('Recarga concluÃ­da: +'+charge+' cÃ©lulas de plasma.');refreshStationMarket();savePosition()}else if(id==='buyUpgrade'){if(credits<80){setStationMessage(insufficientCreditsMessage(80));return}credits-=80;weaponSystem.upgraded=true;weaponSystem.damage=10;setStationMessage('Capacitor MK-II instalado. Dano do canhÃ£o de pulso elevado para 42.');refreshStationMarket();savePosition()}},true);
document.querySelector('#repairHull').addEventListener('click',async()=>{const button=document.querySelector('#repairHull');const maxHull=shipClass==='attack'?180:shipClass==='freighter'?170:100;if(shipHull>=maxHull||credits<40||!stationIds.includes(selected.id)||dist3(player,selected)>2200||window.crewRole==='copilot'){setStationMessage('Reparo indisponÃ­vel: aproxime-se da estaÃ§Ã£o e verifique o saldo e o casco.');return}button.disabled=true;try{let repaired=Math.min(25,maxHull-shipHull);if(multiplayerEnabled){const result=await socialRequest('station-repair',{station:selected.id});shipHull=Number(result.hull);credits=Number(result.credits);repaired=Number(result.repaired)}else{credits-=40;shipHull+=repaired}combatMessage='CASCO REPARADO Â· +'+repaired+'%';setStationMessage('Kit aplicado: +'+repaired+'% de casco por 40 CR.');refreshStationMarket();updateHud();savePosition()}catch(error){setStationMessage(error.message||'NÃ£o foi possÃ­vel reparar o casco.')}finally{button.disabled=false;refreshStationMarket()}});
document.querySelector('#buySingularity').addEventListener('click',async()=>{const button=document.querySelector('#buySingularity');if(button.disabled)return;if(weaponSystem.owned.includes('singularity')){equipWeapon('singularity');return}if(credits<50000){setStationMessage(insufficientCreditsMessage(50000));return}button.disabled=true;try{if(multiplayerEnabled){const response=await socialRequest('weapon-purchase',{station:selected.id});credits=Number(response.credits);miningState.oreCounts={Ferro:Number(response.cargo.Ferro),Niquel:Number(response.cargo.Niquel),Cobalto:Number(response.cargo.Cobalto)};miningState.ore=Object.values(miningState.oreCounts).reduce((a,b)=>a+b,0)}else{if(credits<50000||miningState.oreCounts.Ferro<1000||miningState.oreCounts.Niquel<700||miningState.oreCounts.Cobalto<300)throw new Error('Requer 50.000 CR, 1.000 kg Fe, 700 kg Ni e 300 kg Co.');credits-=50000;miningState.oreCounts.Ferro-=1000;miningState.oreCounts.Niquel-=700;miningState.oreCounts.Cobalto-=300;miningState.ore=Object.values(miningState.oreCounts).reduce((a,b)=>a+b,0)}weaponSystem.kind='singularity';weaponSystem.owned=Array.from(new Set([...weaponSystem.owned,'singularity']));weaponSystem.installed=true;weaponSystem.upgraded=false;weaponSystem.damage=Math.round(150*(shipClass==='attack'?1.35:1));weaponSystem.maxAmmo=30;weaponSystem.ammo=30;setStationMessage('CanhÃ£o de cerco instalado. 30 cargas; impacto de 150.');refreshStationMarket();updateHud();savePosition();stationBank.refresh()}catch(error){setStationMessage(error.message||'Nao foi possivel comprar o canhao.');refreshStationMarket()}});
document.querySelectorAll('[data-refuel]').forEach(button=>button.addEventListener('click',async()=>{if(button.disabled)return;button.disabled=true;try{const requested=Math.min(fuelCapacityUnits-fuelUnits,button.dataset.refuel==='fill'?Math.ceil(fuelCapacityUnits-fuelUnits):Number(button.dataset.refuel));if(requested<=0){setStationMessage('Tanque jÃ¡ estÃ¡ cheio.');return}if(multiplayerEnabled){const result=await socialRequest('station-refuel',{station:selected.id,amount:requested});fuelUnits=Number(result.fuel);credits=Number(result.credits)}else{const quantity=Math.min(requested,fuelCapacityUnits-fuelUnits),cost=Math.ceil(quantity/10);if(credits<cost)throw new Error('Creditos insuficientes para o reabastecimento.');fuelUnits+=quantity;credits-=cost}setStationMessage('Reabastecimento concluido - combustivel '+fuelUnits.toLocaleString('pt-BR')+' U.');refreshStationMarket();updateHud();savePosition()}catch(error){setStationMessage(error.message)}finally{button.disabled=false}}));document.querySelector('#sellIronAmount').addEventListener('input',refreshStationMarket);
