canvas.addEventListener('click',event=>{const rect=canvas.getBoundingClientRect(),mx=(event.clientX-rect.left)*W/rect.width,my=(event.clientY-rect.top)*H/rect.height;let candidate=null,best=Infinity;for(const {b:body} of near){if(body.type!=='EstaÃ§Ã£o')continue;const p=project(body);if(!p||p.r<.7)continue;const radius=Math.max(34,Math.min(150,p.r*1.75)),distance=Math.hypot(mx-p.x,my-p.y);if(distance<=radius&&distance<best){best=distance;candidate=body}}if(candidate)openStationMarket(candidate)});
