canvas.addEventListener('click',event=>{if(!multiplayerEnabled)return;const rect=canvas.getBoundingClientRect(),mx=(event.clientX-rect.left)*W/rect.width,my=(event.clientY-rect.top)*H/rect.height;let found=null,best=Infinity;for(const ship of remoteShips){const info=remoteShipRenderInfo(ship);if(!info)continue;const px=info.mode==='ship'?info.point.x:info.x,py=info.mode==='ship'?info.point.y:info.y,radius=info.mode==='ship'?Math.max(30,clamp(48000/info.point.z,16,29)*2.35):27,distance=Math.hypot(mx-px,my-py);if(distance<radius&&distance<best){best=distance;found=ship}}if(found){event.preventDefault();event.stopImmediatePropagation();combatTargetId=Number(found.id);const rescueButton=document.querySelector('#profileTowAction');if(rescueButton){const needsRescue=Number(found.fuel)<=0&&Number(found.hull)>0;rescueButton.hidden=!needsRescue;rescueButton.disabled=false;rescueButton.textContent='SOLICITAR REBOQUE';}openPilotProfile(found.id);return}const wreckHit=lootDrops.map(wreck=>({wreck,point:project({x:wreck.x,y:0,z:wreck.z,r:30})})).filter(item=>item.point&&Math.hypot(mx-item.point.x,my-item.point.y)<Math.max(22,item.point.r+12)).sort((a,b)=>Math.hypot(mx-a.point.x,my-a.point.y)-Math.hypot(mx-b.point.x,my-b.point.y))[0];if(wreckHit)openWreck(wreckHit.wreck)});
