async function setupVoicePeer(){if(callPeerConnection)return;callLocalStream=await navigator.mediaDevices.getUserMedia({audio:true,video:callVideoEnabled?{width:{ideal:1280},height:{ideal:720}}:false});callPeerConnection=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});for(const track of callLocalStream.getTracks())callPeerConnection.addTrack(track,callLocalStream);if(callVideoEnabled){document.querySelector('#callVideoStage').hidden=false;document.querySelector('#localCallVideo').srcObject=callLocalStream}callPeerConnection.onicecandidate=event=>{if(event.candidate)sendCallSignal('ice',event.candidate.toJSON())};callPeerConnection.ontrack=event=>{const audio=document.querySelector('#remoteCallAudio');audio.srcObject=event.streams[0];audio.play().catch(()=>{});if(event.track.kind==='video'){callVideoEnabled=true;document.querySelector('#callVideoStage').hidden=false;document.querySelector('#remoteCallVideo').srcObject=event.streams[0];document.querySelector('#remoteCallVideo').play().catch(()=>{})}};callPeerConnection.onconnectionstatechange=()=>{if(callPeerConnection&&['failed','closed'].includes(callPeerConnection.connectionState))endVoiceCall(true,'A conexÃ£o de voz foi interrompida.')}}
async function startVoiceCall(userId,name,withVideo=false){try{callVideoEnabled=Boolean(withVideo);const data=await socialRequest('call-start',{user_id:userId});activeCallId=data.call_id;callRole='caller';callPeerId=userId;callPeerName=name;callAccepted=false;callSocket?.ring(activeCallId,callVideoEnabled);setCallView((callVideoEnabled?'CHAMADA DE VIDEO PARA ':'CHAMANDO ')+name.toUpperCase(),callVideoEnabled?'Aguardando o piloto atender a chamada de video?':'Aguardando o piloto atender?');await setupVoicePeer();const offer=await callPeerConnection.createOffer();await callPeerConnection.setLocalDescription(offer);await sendCallSignal('offer',callPeerConnection.localDescription.toJSON())}catch(error){if(activeCallId)await postCallControl('call-end');stopVoiceMedia();activeCallId='';setCallView('CHAMADA NAO INICIADA',error.message,'done');setTimeout(closeCallView,2600)}}
