async function acceptVoiceCall(){try{window.naveCallRingtone?.stop();await socialRequest('call-accept',{call_id:activeCallId});callSocket?.notify(activeCallId);callAccepted=true;setCallView((callVideoEnabled?'VIDEO COM ':'LIGACAO COM ')+callPeerName.toUpperCase(),'Conectando a chamada...');if(!pendingCallOffer)await new Promise(resolve=>{const started=Date.now(),timer=setInterval(()=>{if(pendingCallOffer||Date.now()-started>2800){clearInterval(timer);resolve()}},100)});if(/m=video/i.test(String(pendingCallOffer?.sdp||'')))callVideoEnabled=true;setCallView((callVideoEnabled?'VIDEO COM ':'LIGACAO COM ')+callPeerName.toUpperCase(),callVideoEnabled?'Conectando camera e audio?':'Conectando o audio?');await setupVoicePeer();if(pendingCallOffer)await answerIncomingOffer()}catch(error){await postCallControl('call-end');stopVoiceMedia();activeCallId='';callRole='';setCallView('ERRO NA LIGACAO',error.message,'done');setTimeout(closeCallView,2600)}}
