async function handleCallSignal(signal){if(signal.call_id!==activeCallId)return;try{if(signal.signal_type==='offer'){pendingCallOffer=signal.payload;if(/m=video/i.test(String(signal.payload?.sdp||''))){callVideoEnabled=true;document.querySelector('#callTitle').textContent='CHAMADA DE VIDEO DE '+callPeerName.toUpperCase();if(callRole==='callee'&&!callAccepted)document.querySelector('#callStatus').textContent='Convite de v?deo recebido. Toque em ATENDER para aceitar.';document.querySelector('#callVideoStage').hidden=false}if(callRole==='callee'&&callAccepted)await answerIncomingOffer()}else if(signal.signal_type==='answer'&&callRole==='caller'&&callPeerConnection&&!callPeerConnection.remoteDescription){await callPeerConnection.setRemoteDescription(new RTCSessionDescription(signal.payload));await flushCallIce();setCallView('LIGAÃ‡ÃƒO COM '+callPeerName.toUpperCase(),'Microfone conectado ? chamada de voz ativa.')}else if(signal.signal_type==='ice'){if(callPeerConnection?.remoteDescription)await callPeerConnection.addIceCandidate(new RTCIceCandidate(signal.payload));else pendingCallIce.push(signal.payload)}}catch(error){document.querySelector('#callStatus').textContent='Falha na conexÃ£o de Ã¡udio: '+error.message}}
callSocket=window.createCallSocket({api:multiplayerApi,enabled:multiplayerEnabled,onEvent:async event=>{if(event.type==='call_invite'&&!activeCallId){window.naveCallRingtone?.start();activeCallId=String(event.callId);callRole='callee';callAccepted=false;callVideoEnabled=Boolean(event.video);callPeerId=Number(event.callerId);callPeerName=String(event.callerName||'PILOTO');setCallView((callVideoEnabled?'CHAMADA DE VIDEO DE ':'CHAMADA DE ')+callPeerName.toUpperCase(),callVideoEnabled?'Quer atender a chamada de video?':'Quer atender a chamada de audio?','incoming')}else if(event.type==='call_state'&&event.callId===activeCallId){if(event.status==='accepted'&&callRole==='caller'){callAccepted=true;callOverlay.classList.add('mc-call-active');document.querySelector('#callStatus').textContent='Piloto atendeu ? conectando Ã¡udioâ€¦'}else if(['declined','missed','ended'].includes(event.status)){endVoiceCall(false,event.status==='declined'?'O piloto recusou a ligaÃ§Ã£o.':event.status==='missed'?'O piloto nÃ£o atendeu.':'A ligaÃ§Ã£o foi encerrada pelo outro piloto.')}}else if(event.type==='signal'){await handleCallSignal({call_id:String(event.callId),signal_type:event.signalType,payload:event.payload})}}});
