let lastCallPollBusy=false;async function pollCalls(){if(!multiplayerEnabled||lastCallPollBusy)return;lastCallPollBusy=true;try{const data=await socialRequest('call-poll');for(const call of data.calls||[]){const id=String(call.call_id),isCaller=Number(call.caller_id)===multiplayerUserId;if(activeCallId&&id===activeCallId){if(call.status==='accepted'&&callRole==='caller'){callAccepted=true;callOverlay.classList.add('mc-call-active');document.querySelector('#callStatus').textContent='Piloto atendeu ? conectando Ã¡udioâ€¦'}else if(['declined','missed','ended'].includes(call.status)){endVoiceCall(false,call.status==='declined'?'O piloto recusou a ligaÃ§Ã£o.':call.status==='missed'?'O piloto nÃ£o atendeu.':'A ligaÃ§Ã£o foi encerrada pelo outro piloto.')}}else if(!activeCallId&&call.status==='ringing'&&!isCaller){const videoOffer=(data.signals||[]).find(signal=>String(signal.call_id)===id&&signal.signal_type==='offer'&&/m=video/i.test(String(signal.payload?.sdp||'')));window.naveCallRingtone?.start();activeCallId=id;callRole='callee';callAccepted=false;callVideoEnabled=Boolean(videoOffer);callPeerId=Number(call.caller_id);callPeerName=call.caller_name;setCallView((callVideoEnabled?'CHAMADA DE VIDEO DE ':'CHAMADA DE ')+String(call.caller_name).toUpperCase(),callVideoEnabled?'Convite de v?deo recebido. Toque em ATENDER para aceitar.':'Quer atender a chamada de audio?','incoming')}}for(const signal of data.signals||[])await handleCallSignal(signal)}catch(error){}finally{lastCallPollBusy=false}}
