const jettisonStyle=document.createElement('style');jettisonStyle.textContent=`.jettison-overlay{position:fixed;inset:0;z-index:62;display:none;place-items:center;padding:18px;background:rgba(1,7,15,.85);backdrop-filter:blur(9px)}.jettison-overlay.open{display:grid}.jettison-card{width:min(440px,94vw);padding:20px;background:linear-gradient(145deg,#102633,#07131e);border:1px solid rgba(255,183,121,.48);box-shadow:0 0 45px rgba(255,139,67,.15)}.jettison-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.jettison-close{display:grid;place-items:center;flex:none;width:34px;height:34px;border:1px solid rgba(120,195,204,.32);border-radius:50%;background:rgba(7,25,36,.8);color:#c2ebeb;font:22px/1 sans-serif;cursor:pointer}.jettison-close:hover{border-color:#71e7f3;color:#fff;box-shadow:0 0 14px #4bcfe533}.jettison-row[hidden]{display:none!important}.jettison-card h2{margin:6px 0 8px;font-size:25px;font-weight:500}.jettison-copy,.jettison-status{color:#97b0b6;font-size:13px;line-height:1.45}.jettison-row{display:grid;grid-template-columns:1fr 90px;gap:8px;align-items:center;margin:8px 0;padding:9px;border:1px solid rgba(120,180,190,.16);background:#091923;color:#d1e7e8;font:9px 'Space Mono'}.jettison-row small{display:block;margin-top:4px;color:#769ba5;font-size:7px}.jettison-row input{width:100%;padding:8px;background:#06121b;color:#f1fbfa;border:1px solid rgba(116,196,205,.3);font:10px 'Space Mono'}.jettison-actions{display:flex;gap:8px;margin-top:12px}.jettison-actions button{flex:1;padding:10px;border:1px solid rgba(120,195,204,.32);background:#0a2330;color:#c2ebeb;font:8px 'Space Mono';cursor:pointer}.jettison-actions button.primary{border-color:#e5a76e;color:#ffe0bf;background:rgba(115,61,31,.3)}.jettison-actions button:disabled{opacity:.45}.jettison-drop-zone{position:fixed;inset:0;z-index:80;display:grid;place-items:center;pointer-events:none;opacity:0;transition:opacity .18s;background:radial-gradient(ellipse at center,rgba(11,45,57,.12),rgba(2,9,18,.58))}.jettison-drop-zone span{padding:18px 26px;border:1px dashed rgba(130,244,236,.65);border-radius:18px;background:rgba(4,23,34,.9);color:#c9ffff;font:11px 'Space Mono';letter-spacing:.12em;box-shadow:0 0 45px rgba(66,227,219,.18)}body.cargo-drop-active .jettison-drop-zone{opacity:1}body.cargo-drop-hover .jettison-drop-zone span{border-style:solid;background:rgba(17,72,80,.95);box-shadow:0 0 55px rgba(66,227,219,.38);transform:scale(1.04)}@media(max-width:480px){.jettison-card{padding:15px}}`;document.head.appendChild(jettisonStyle);document.body.insertAdjacentHTML('beforeend',`<div class="jettison-drop-zone" id="jettisonDropZone"><span>SOLTE PARA LIBERAR A CARGA NO ESPAÇO</span></div><div class="jettison-overlay" id="jettisonOverlay" aria-hidden="true"><section class="jettison-card" role="dialog" aria-modal="true"><div class="jettison-heading"><div class="eyebrow">LIBERAÇÃO DE CARGA / SETOR ABERTO · 24 H</div><button type="button" class="jettison-close" id="jettisonCloseTop" aria-label="Fechar">�</button></div><h2>Preparar contêiner espacial</h2><p class="jettison-copy">Revise a quantidade antes de liberar. O contêiner ficará visível para todos os pilotos por 24 horas; qualquer um poderá recolher o que houver nele.</p><label class="jettison-row"><span>Minério de ferro <small id="dropAvailIron">0 kg disponíveis</small></span><input id="dropIron" type="number" min="0" step="1" value="0"></label><label class="jettison-row"><span>Níquel <small id="dropAvailNickel">0 kg disponíveis</small></span><input id="dropNickel" type="number" min="0" step="1" value="0"></label><label class="jettison-row"><span>Cobalto <small id="dropAvailCobalt">0 kg disponíveis</small></span><input id="dropCobalt" type="number" min="0" step="1" value="0"></label><div class="jettison-status" id="jettisonStatus"></div><div class="jettison-actions"><button type="button" id="jettisonClose">CANCELAR</button><button type="button" class="primary" id="jettisonConfirm">LIBERAR CONTÊINER<