const jettisonOverlay=document.querySelector('#jettisonOverlay'),jettisonDropZone=document.querySelector('#jettisonDropZone');let pendingJettisonPosition=null;function closeJettison(){jettisonOverlay.classList.remove('open');jettisonOverlay.setAttribute('aria-hidden','true');pendingJettisonPosition=null}function openJettisonModal(kind='ore',dropPosition=null){if(!multiplayerEnabled){combatMessage='Entre no multiplayer para compartilhar carga com outros pilotos.';document.querySelector('#combatStatus').textContent=combatMessage;return}const available={Ferro:Number(miningState.oreCounts.Ferro)||0,Niquel:Number(miningState.oreCounts.Niquel)||0,Cobalto:Number(miningState.oreCounts.Cobalto)||0},rows={Ferro:document.querySelector('#dropIron').closest('.jettison-row'),Niquel:document.querySelector('#dropNickel').closest('.jettison-row'),Cobalto:document.querySelector('#dropCobalt').closest('.jettison-row')},inputs={Ferro:document.querySelector('#dropIron'),Niquel:document.querySelector('#dropNickel'),Cobalto:document.querySelector('#dropCobalt')},selectedMineral={iron:'Ferro',nickel:'Niquel',cobalt:'Cobalto'}[kind];for(const mineral of Object.keys(available)){const amount=Math.max(0,Math.floor(available[mineral]));rows[mineral].hidden=amount===0;inputs[mineral].max=String(amount);inputs[mineral].value='0';document.querySelector('#dropAvail'+({Ferro:'Iron',Niquel:'Nickel',Cobalto:'Cobalt'}[mineral])).textContent=amount.toLocaleString('pt-BR')+' kg dispon�veis'}const unavailable=window.crewDocked||shipHull<=0||Object.values(available).every(amount=>amount<=0);document.querySelector('#jettisonConfirm').disabled=unavailable;if(window.crewDocked||shipHull<=0)document.querySelector('#jettisonStatus').textContent=window.crewDocked?'Desacople a nave para liberar carga no espa�o.':'Sua nave precisa estar operacional.';else if(unavailable)document.querySelector('#jettisonStatus').textContent='Nenhum min�rio dispon�vel para liberar.';else document.querySelector('#jettisonStatus').textContent=dropPosition?'Ponto de libera��o definido pela �rea onde voc� soltou o recurso. O espa�o � compartilhado por todos os pilotos.':'O cont�iner aparecer� junto � posi��o atual da sua nave.';pendingJettisonPosition=dropPosition;if(selectedMineral&&available[selectedMineral]>0){inputs[selectedMineral].value=String(Math.floor(available[selectedMineral]));inputs[selectedMineral].focus();inputs[selectedMineral].select()}jettisonOverlay.classList.add('open');jettisonOverlay.setAttribute('aria-hidden','false')}document.addEventListener('navestar:cargo-discard-request',event=>{if(!['ore','ice'].includes(event.detail?.kind))return;openJettisonModal(event.detail.kind)});document.addEventListener('navestar:cargo-drag-start',event=>{if(!['ore','ice'].includes(event.detail?.kind))return;document.body.classList.add('cargo-drop-active');jettisonDropZone.dataset.kind=event.detail.kind;jettisonDropZone.style.pointerEvents='auto'});document.addEventListener('navestar:cargo-drag-end',()=>{document.body.classList.remove('cargo-drop-active','cargo-drop-hover');jettisonDropZone.style.pointerEvents='none'});const gameDropTargets=[canvas,document.querySelector('#space')].filter(Boolean);gameDropTargets.push(jettisonDropZone);gameDropTargets.forEach(target=>{target.addEventListener('dragover',event=>{if(!document.body.classList.contains('cargo-drop-active'))return;event.preventDefault();event.dataTransfer.dropEffect='copy';document.body.classList.add('cargo-drop-hover')});target.addEventListener('dragleave',event=>{if(!target.contains(event.relatedTarget))document.body.classList.remove('cargo-drop-hover')});target.addEventListener('drop',event=>{if(!document.body.classList.contains('cargo-drop-active'))return;event.preventDefault();const kind=event.dataTransfer.getData('application/x-navestar-cargo')||event.dataTransfer.getData('text/plain'),rect=canvas.getBoundingClientRect(),localX=clamp((event.clientX-rect.left)/rect.width,0,1),localY=clamp((event.clientY-rect.top)/rect.height,0,1),angle=player.yaw||0,lateral=(localX-.5)*22000,forward=(.5-localY)*22000,position={x:player.x+Math.cos(angle)*forward-Math.sin(angle)*lateral,z:player.z+Math.sin(angle)*forward+Math.cos(angle)*lateral};document.body.classList.remove('cargo-drop-active','cargo-drop-hover');jettisonDropZone.style.pointerEvents='none';openJettisonModal(kind,position)})});document.querySelector('#jettisonClose').addEventListener('click',closeJettison);document.querySelector('#jettisonCloseTop').addEventListener('click',closeJettison);jettisonOverlay.addEventListener('click',event=>{if(event.target===jettisonOverlay)closeJettison()});document.querySelector('#jettisonConfirm').addEventListener('click',async()=>{const button=document.querySelector('#jettisonConfirm'),cargo={Ferro:Math.max(0,Math.floor(Number(document.querySelector('#dropIron').value)||0)),Niquel:Math.max(0,Math.floor(Number(document.querySelector('#dropNickel').value)||0)),Cobalto:Math.max(0,Math.floor(Number(document.querySelector('#dropCobalt').value)||0))},available={Ferro:Number(miningState.oreCounts.Ferro)||0,Niquel:Number(miningState.oreCounts.Niquel)||0,Cobalto:Number(miningState.oreCounts.Cobalto)||0};if(Object.keys(cargo).some(mineral=>cargo[mineral]>available[mineral])){document.querySelector('#jettisonStatus').textContent='A quantidade escolhida excede o min�rio dispon�vel no compartimento.';return}button.disabled=true;try{const result=await socialRequest('cargo-jettison',{cargo,position:pendingJettisonPosition});for(const [mineral,amount] of Object.entries(result.cargo||{}))miningState.oreCounts[mineral]=Math.max(0,(Number(miningState.oreCounts[mineral])||0)-Number(amount));miningState.ore=Object.values(miningState.oreCounts).reduce((sum,value)=>sum+value,0);combatMessage='Contêiner compartilhado liberado no setor por 24 horas.';savePosition();await pollCombatWorld();closeJettison()}catch(error){document.querySelector('#jettisonStatus').textContent=error.message}finally{button.disabled=false}});

